    private void jButton2ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton2ActionPerformed
   String path = jTextField1.getText().trim();
    if (path.isEmpty()) {
        javax.swing.JOptionPane.showMessageDialog(this, "Please select a folder first!");
        return;
    }

    // 1. Update Progress Bar
    jProgressBar1.setStringPainted(true);
    jProgressBar1.setValue(100);
    jProgressBar1.setString("Scan Complete");

    // 2. Clear old table rows
    javax.swing.table.DefaultTableModel model = (javax.swing.table.DefaultTableModel) jTable1.getModel();
    model.setRowCount(0);

    // 3. Recursively scan all files in the directory (supports all file types)
    java.io.File rootDir = new java.io.File(path);
    java.util.List<java.io.File> allFiles = new java.util.ArrayList<>();
    collectAllFiles(rootDir, allFiles);

    // 4. Populate table with real files found on disk
    for (java.io.File file : allFiles) {
        model.addRow(new Object[]{false, file.getName(), file.getAbsolutePath(), file.length()});
    }
}

// Helper method to gather all files recursively across all subdirectories
private void collectAllFiles(java.io.File dir, java.util.List<java.io.File> fileList) {
    java.io.File[] files = dir.listFiles();
    if (files != null) {
        for (java.io.File f : files) {
            if (f.isDirectory()) {
                collectAllFiles(f, fileList);
            } else {
                fileList.add(f);
            }
        }
    }
    }//GEN-LAST:event_jButton2ActionPerformed

    private void jButton1ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton1ActionPerformed
        // Create a file chooser object
    javax.swing.JFileChooser fileChooser = new javax.swing.JFileChooser();
    
    // Set it to select directories/folders only (not individual files)
    fileChooser.setFileSelectionMode(javax.swing.JFileChooser.DIRECTORIES_ONLY);
    
    // Open the folder selection dialog window
    int option = fileChooser.showOpenDialog(this);
    
    // If the user selects a folder and clicks "Open"
    if (option == javax.swing.JFileChooser.APPROVE_OPTION) {
        java.io.File selectedFolder = fileChooser.getSelectedFile();
        // Display the folder path in the text field
        jTextField1.setText(selectedFolder.getAbsolutePath());
    }
    }//GEN-LAST:event_jButton1ActionPerformed

    private void jButton3ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton3ActionPerformed
javax.swing.table.DefaultTableModel model = (javax.swing.table.DefaultTableModel) jTable1.getModel();
    int rowCount = model.getRowCount();
    java.util.List<String> filesToQuarantine = new java.util.ArrayList<>();

    // 1. Loop through table rows and check column 0 (checkbox)
    for (int i = 0; i < rowCount; i++) {
        Boolean isSelected = (Boolean) model.getValueAt(i, 0);
        if (isSelected != null && isSelected) {
            String filePath = (String) model.getValueAt(i, 2);
            filesToQuarantine.add(filePath);
        }
    }

    // 2. Validation: Check if user actually selected any files
    if (filesToQuarantine.isEmpty()) {
        javax.swing.JOptionPane.showMessageDialog(this, 
            "Please check at least one duplicate file to process!", 
            "No Files Selected", 
            javax.swing.JOptionPane.WARNING_MESSAGE);
        return;
    }

    // 3. Confirmation Dialog
    int confirm = javax.swing.JOptionPane.showConfirmDialog(this, 
        "Are you sure you want to process " + filesToQuarantine.size() + " file(s)?", 
        "Confirm Action", 
        javax.swing.JOptionPane.YES_NO_OPTION);

    if (confirm == javax.swing.JOptionPane.YES_OPTION) {
        boolean useRecycleBin = jCheckBoxRecycle.isSelected();
        
        try {
            if (useRecycleBin && java.awt.Desktop.isDesktopSupported()) {
                // Sends files directly to system recycling bin / trash
                for (String path : filesToQuarantine) {
                    java.awt.Desktop.getDesktop().moveToTrash(new java.io.File(path));
                }
                javax.swing.JOptionPane.showMessageDialog(this, 
                    "Selected files have been sent to the Recycle Bin!", 
                    "Success", 
                    javax.swing.JOptionPane.INFORMATION_MESSAGE);
            } else {
                // Placeholder for your teammate's custom quarantine logic tomorrow
                System.out.println("Files ready for custom quarantine: " + filesToQuarantine);
                javax.swing.JOptionPane.showMessageDialog(this, 
                    "Files selected! Ready for backend integration tomorrow.", 
                    "Pending Backend", 
                    javax.swing.JOptionPane.INFORMATION_MESSAGE);
            }
                
        } catch (Exception e) {
            javax.swing.JOptionPane.showMessageDialog(this, 
                "Error processing files: " + e.getMessage(), 
                "Error", 
                javax.swing.JOptionPane.ERROR_MESSAGE);
        }
    }
    }//GEN-LAST:event_jButton3ActionPerformed

